<script setup lang="ts">import { onMounted, ref } from 'vue'; import { useRouter } from 'vue-router'; import { fetchCategories, createCategory, renameCategory, deleteCategory, getApiErrorMessage, type CategoryResponse } from '../api/http'; const router=useRouter(); const items=ref<CategoryResponse[]>([]); const name=ref(''); const error=ref(''); const editing=ref<number|null>(null); const editName=ref(''); const loading=ref(true); async function load(){loading.value=true; try{items.value=await fetchCategories()}catch(e){error.value=getApiErrorMessage(e,'服务器列表加载失败，请重试。')}finally{loading.value=false}} onMounted(load); async function add(){if(!name.value.trim())return; try{items.value.push(await createCategory(name.value.trim()));name.value=''}catch(e){error.value=getApiErrorMessage(e,'服务器创建失败，请检查名称。')}} async function save(item:CategoryResponse){if(!editName.value.trim())return; try{const v=await renameCategory(item.id,editName.value.trim());Object.assign(item,v);editing.value=null}catch(e){error.value=getApiErrorMessage(e,'服务器重命名失败，请检查名称是否重复。')}} async function remove(item:CategoryResponse){try{await deleteCategory(item.id);items.value=items.value.filter(x=>x.id!==item.id)}catch(e){error.value=getApiErrorMessage(e,'服务器仍被反馈使用，无法删除；请先重命名或迁移反馈。')}}</script>
<template><main class="form-page"><button class="back-link" @click="router.push('/admin')">← 返回管理面板</button><section class="form-panel"><p class="eyebrow">SERVERS</p><h1>服务器管理</h1><p class="form-lede">可重命名已有服务器；相关反馈会自动迁移到新名称。删除前请先处理仍属于该服务器的反馈。</p><p v-if="loading">正在加载服务器…</p><div class="tag-directory"><div v-for="item in items" :key="item.id" class="tag-directory-row"><template v-if="editing===item.id"><input v-model="editName" @keyup.enter="save(item)" /><button class="secondary-button" @click="save(item)">保存</button><button class="tag-cancel" @click="editing=null">取消</button></template><template v-else><strong>{{item.name}}</strong><span>{{item.issueCount}} 条开放反馈</span><button class="secondary-button" @click="editing=item.id;editName=item.name">重命名</button><button class="tag-delete" @click="remove(item)">删除</button></template></div></div><form class="tag-create-form" @submit.prevent="add"><label>新服务器名称<input v-model="name" maxlength="32" /></label><button class="primary-button">创建服务器</button></form><p v-if="error" class="form-error">{{error}}</p></section></main></template>
